import{z as s,x as o,o as e,c as C,q as r,j as t,D as a,d as B,s as n,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"偏好数据的全生命周期","description":"","frontmatter":{"title":"偏好数据的全生命周期","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-preference-lifecycle.md","filePath":"llm/ade-preference-lifecycle.md","lastUpdated":1791063341000}'),D={name:"llm/ade-preference-lifecycle.md"};function d(p,E,m,c,f,T){const l=o("Mermaid");return e(),C("div",null,[E[2]||(E[2]=r('<h1 id="偏好数据的全生命周期" tabindex="-1">偏好数据的全生命周期 <a class="header-anchor" href="#偏好数据的全生命周期" aria-label="Permalink to &quot;偏好数据的全生命周期&quot;">​</a></h1><div class="epigraph"><p>偏好数据不是一次采集，而是一份随策略移动而贬值的资产：它有版本、有账本，也有退役日。</p><footer>—— 据 Ouyang 等 InstructGPT 2022、Touvron 等 Llama 2 2023 的多轮迭代口径整理</footer></div><p><a href="/llm/ce-map">上一课</a>把推理成本工程收成三单元一线与八问决策单：先口径后杠杆，验证永远成本、延迟、质量三列同看。深钻层在这里换挡：从算钱换到喂数——<a href="/llm/rm-engineering-map">奖励模型工程</a>立过「数据定天花板」的主干结论，本课程把这句话当一门独立工程来做：对齐数据工程。第一课写偏好数据的全生命周期：从规划、采集、标注、入库，到消费、回流、退役。<a href="/llm/rm-data-sources">偏好数据的来源谱系</a>已经把「比较对从哪来」钉成四类源的谱系；本课把谱系放进时间轴：数据不是名词，是一份有版本的资产。后课默认本课的资产观已就位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>常见做法是把偏好数据当一次性耗材：采一批、训一版、脚本归档。三个月后政策改版，没人说得清库里哪批数据按哪版指南标的、哪批已经过期；模型出了问题想回查数据，发现「数据」只是一个没有账本的文件夹。失效形态有三。版本缺失：指南与政策改了，旧数据被静默混用，判断锚已经换了。无回流：部署后收集到的失败案例不回数据管线，下一轮从零再采。无退役：过期数据与新数据等权混训，RM 的边界被旧分布拖住。缺口不是某个技巧，而是把数据当资产管理的那张生命周期表：每段有产物、有门、有责任人。</p><p><span class="marginnote">把数据当耗材还是当资产，可以类比发传单和图书馆：发传单用完就扔，谁也说不清发过哪些；图书馆每本书有编号、借阅记录和下架日期。三个月后政策改版时，前者只能重买一遍书，后者按编号一查就知道哪些书是按旧规则编目的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生命周期八段，每段有产物与门。规划段写数据卡草稿：目标行为、政策版本、指南版本。采集段产出提示与候选，候选混采自当前策略及其近邻（来源课的口径）。标注段产出比较对与一致率。质检入库段跑去重、隐私剥离与一致率门（后课展开），产物是带数据卡版本的入库批次。消费段按配比进训练。回流段收集部署失败与用户反馈，折进下一轮采集的域配额。退役段按规则给批次打过期标记：政策版本变更或策略大版本移动后，比较对降权或归档，提示库保留。八段不是流水线而是循环：回流与退役把第 \\(N\\) 轮的账带进第 \\(N+1\\) 轮。</p>',8)),(e(),t(i,null,{default:a(()=>[n(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAN%5B%22%E8%A7%84%E5%88%92%EF%BC%9A%E7%9B%AE%E6%A0%87%E8%A1%8C%E4%B8%BA%20%2B%20%E6%94%BF%E7%AD%96%2F%E6%8C%87%E5%8D%97%E7%89%88%E6%9C%AC%22%5D%20--%3E%20COLLECT%5B%22%E9%87%87%E9%9B%86%EF%BC%9A%E6%8F%90%E7%A4%BA%20%2B%20%E5%80%99%E9%80%89%E6%B7%B7%E9%87%87%22%5D%0A%20%20COLLECT%20--%3E%20LABEL%5B%22%E6%A0%87%E6%B3%A8%EF%BC%9A%E6%AF%94%E8%BE%83%E5%AF%B9%20%2B%20%E4%B8%80%E8%87%B4%E7%8E%87%22%5D%0A%20%20LABEL%20--%3E%20GATE%5B%22%E8%B4%A8%E6%A3%80%E5%85%A5%E5%BA%93%EF%BC%9A%E5%8E%BB%E9%87%8D%20%2F%20%E9%9A%90%E7%A7%81%20%2F%20%E4%B8%80%E8%87%B4%E7%8E%87%E9%97%A8%22%5D%0A%20%20GATE%20--%3E%20CARD%5B%22%E6%95%B0%E6%8D%AE%E5%8D%A1%E7%89%88%E6%9C%AC%22%5D%0A%20%20CARD%20--%3E%20TRAIN%5B%22%E6%B6%88%E8%B4%B9%EF%BC%9A%E6%8C%89%E9%85%8D%E6%AF%94%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRAIN%20--%3E%20DEPLOY%5B%22%E9%83%A8%E7%BD%B2%22%5D%0A%20%20DEPLOY%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%E4%B8%8E%E5%8F%8D%E9%A6%88%E5%9B%9E%E6%B5%81%22%7C%20COLLECT%0A%20%20DEPLOY%20--%3E%7C%22%E7%AD%96%E7%95%A5%E7%A7%BB%E5%8A%A8%22%7C%20RETIRE%5B%22%E9%80%80%E5%BD%B9%EF%BC%9A%E6%89%B9%E6%AC%A1%E9%99%8D%E6%9D%83%20%2F%20%E5%BD%92%E6%A1%A3%22%5D%0A%20%20RETIRE%20--%3E%20COLLECT%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"为什么必须是循环而不是流水线：偏好数据的价值绑在两个会移动的锚上。第一个锚是策略——RM 的分辨边界只在策略的支撑内可用，策略每轮移动，旧对子的 \\(y_w \\gt y_l\\) 逐渐描述一个不再存在的分布。第二个锚是定义——指南与政策是「好」的文本定义，文本一改，同一条数据测的东西就换了。数据卡版本的作用是把这两个锚钉进每个模型检查点：分数可以对上「用哪份定义、哪批分布训出来的」。提示层与比较层的半衰期不同：提示不依赖策略，是长寿资产；比较对是耗材。承认这一点，退役规则才有落点——过期的是判断，不是题目。",-1)),E[5]||(E[5]=A("p",null,"数据卡的另一个用途是反向回查：线上出了问题，顺着检查点往回追到具体批次与指南版本：",-1)),(e(),t(i,null,{default:a(()=>[n(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20BUG%5B%22%E7%BA%BF%E4%B8%8A%E5%8F%91%E7%8E%B0%E6%A8%A1%E5%9E%8B%E8%A1%8C%E4%B8%BA%E9%97%AE%E9%A2%98%22%5D%20--%3E%20CKPT%5B%22%E5%AE%9A%E4%BD%8D%E6%A3%80%E6%9F%A5%E7%82%B9%EF%BC%9Av3%22%5D%0A%20%20CKPT%20--%3E%7C%22%E8%AE%AD%E7%BB%83%E6%97%B6%E7%BB%91%E5%AE%9A%22%7C%20CARD%5B%22%E6%9F%A5%E6%95%B0%E6%8D%AE%E5%8D%A1%EF%BC%9A%E8%BD%AE%E6%AC%A1%20N%22%5D%0A%20%20CARD%20--%3E%20GV%5B%22%E6%8C%87%E5%8D%97%E7%89%88%E6%9C%AC%201.2%22%5D%0A%20%20CARD%20--%3E%20PV%5B%22%E6%94%BF%E7%AD%96%E7%89%88%E6%9C%AC%202.0%22%5D%0A%20%20CARD%20--%3E%20BATCH%5B%22%E5%85%A5%E5%BA%93%E6%89%B9%E6%AC%A1%20%2341-45%22%5D%0A%20%20GV%20--%3E%20Q%7B%22%E6%94%BF%E7%AD%96%20%2F%20%E6%8C%87%E5%8D%97%E5%90%8E%E6%9D%A5%E6%94%B9%E7%89%88%E4%BA%86%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E6%94%B9%E4%BA%86%22%7C%20RET%5B%22%E8%AF%A5%E6%89%B9%E5%B7%B2%E8%BF%87%E6%9C%9F%20%E2%86%92%20%E9%99%8D%E6%9D%83%E6%88%96%E9%87%8D%E6%A0%87%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B2%A1%E6%94%B9%22%7C%20FIX%5B%22%E6%9F%A5%E6%A0%87%E6%B3%A8%E6%B5%81%E7%A8%8B%E4%B8%8E%E6%89%B9%E6%AC%A1%E8%B4%A8%E9%87%8F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">「策略的支撑」可以理解成「这个模型写得出来的那些回答的范围」。旧偏好对里的两个回答都是旧模型写的；新模型能力范围变了，旧数据就像用三年前的地图给今天的路导航——大方向可能还行，新修的路已经对不上了。</span></p><p><span class="marginnote">Llama 2-Chat 的 RLHF 按迭代组织：多轮「采新偏好数据—重训 RM—再训策略」，每轮数据与当轮检查点绑定；约 141 万条比较对是一批批攒出来的账本，不是一次性库存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>生命周期表不回答配比——各批次占多少是后面配比课的题；也不回答质检怎么跑——去重与清洗有专课。隐式反馈的回流有隐私与合规约束，本课只给它安放在回流段的位置，规则不在此展开。最后，资产观有成本：数据卡、版本、退役规则都是账面工作，小团队会嫌重；但第一次政策改版就会把省下的这笔账连本带利讨回去——找回「哪批数据按哪版指南标」的时间，远多于当初记账的时间。</p><p><span class="marginnote">「隐式反馈」指用户没被明确问「哪个更好」时留下的信号：点踩、跳过、换个问法重新提问。它便宜但含糊——点踩可能因为答案错了，也可能只是网页卡了；再加上可能夹带个人信息、受合规约束，所以本课只给它留了回流段的位置，规则不展开。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>偏好数据是随策略移动而贬值的资产：有版本、有账本、有退役日。</li><li>生命周期八段成循环：规划、采集、标注、入库、消费、部署、回流、退役；产物是带版本的数据卡。</li><li>两个会移动的锚：策略分布与文本定义；数据卡版本把两者钉进模型检查点。</li><li>提示是长寿资产，比较对是耗材；退役过期的是判断，不是题目。</li><li>出处：Ouyang 等 InstructGPT，2022；Touvron 等 Llama 2，2023 的迭代口径，按本课程整理。</li></ul>',7))])}const h=s(D,[["render",d]]);export{u as __pageData,h as default};
